import { readdir, readFile } from 'node:fs/promises';

const { version: packageVersion } = JSON.parse(await readFile(new URL('../../packages/aesir-html/package.json', import.meta.url), 'utf8'));

const outputDirectory = new URL('../../packages/aesir-html/dist/', import.meta.url);
const outputFile = new URL('aesir-html.min.js', outputDirectory);
const iconsFile = new URL('aesir-icons.min.js', outputDirectory);
const files = await readdir(outputDirectory);
const expectedFiles = ['aesir-html.min.js', 'aesir-icons.min.js', 'aesir-core.css', 'aesir-fonts.css', 'aesir-typography.css', 'components', 'fonts'];

if (expectedFiles.some((file) => !files.includes(file))) {
  throw new Error(`aesir-html must produce ${expectedFiles.join(', ')}. Found: ${files.join(', ') || 'nothing'}`);
}

const source = await readFile(outputFile, 'utf8');
if (!source.includes(JSON.stringify(packageVersion)) || !/version\s*:/.test(source)) {
  throw new Error(`aesir-html runtime version must match package.json (${packageVersion}).`);
}
const iconsSource = await readFile(iconsFile, 'utf8');
const coreCss = await readFile(new URL('aesir-core.css', outputDirectory), 'utf8');

if (source.includes('$$props')) {
  throw new Error('aesir-html contains an unresolved $$props reference generated by an invalid Custom Element slot wrapper.');
}

const expectedElements = (await readdir(new URL('../../packages/aesir-html/src/elements/', import.meta.url)))
  .filter((file) => file.endsWith('.svelte'))
  .map((file) => file.replace(/\.svelte$/, ''))
  .sort();

for (const tag of expectedElements) {
  if (!source.includes(`customElements.define("${tag}"`)) {
    throw new Error(`aesir-html is missing the ${tag} registration.`);
  }
}

const elementFiles = expectedElements.map((tag) => `${tag}.min.js`);
const componentFiles = (await readdir(new URL('components/', outputDirectory))).filter((file) => file.endsWith('.min.js')).sort();

if (componentFiles.length !== elementFiles.length || elementFiles.some((file) => !componentFiles.includes(file))) {
  throw new Error(`aesir-html modular build is incomplete. Expected ${elementFiles.join(', ')}. Found: ${componentFiles.join(', ') || 'nothing'}`);
}

for (const file of componentFiles) {
  const componentSource = await readFile(new URL(`components/${file}`, outputDirectory), 'utf8');
  const tag = file.replace(/\.min\.js$/, '');
  if (!componentSource.includes(tag)) throw new Error(`${file} does not register or load ${tag}.`);
  if (!componentSource.includes(JSON.stringify(packageVersion)) || !/version\s*:/.test(componentSource)) {
    throw new Error(`${file} runtime version must match package.json (${packageVersion}).`);
  }
}

const runtimeFiles = (await readdir(new URL('components/runtime/', outputDirectory))).sort();
if (runtimeFiles.join(',') !== 'aesir-runtime.min.js') {
  throw new Error(`aesir-html modular build must produce exactly one shared runtime. Found: ${runtimeFiles.join(', ') || 'nothing'}`);
}
const runtimeSource = await readFile(new URL('components/runtime/aesir-runtime.min.js', outputDirectory), 'utf8');
if (runtimeSource.length > 100_000) throw new Error(`aesir-html shared runtime is unexpectedly large: ${runtimeSource.length} bytes.`);

const fontFiles = (await readdir(new URL('fonts/', outputDirectory))).sort();
if (fontFiles.join(',') !== 'Inter.woff2,Mono.woff2') {
  throw new Error(`aesir-html fonts or their licenses are incomplete. Found: ${fontFiles.join(', ') || 'nothing'}`);
}
const notices = await readFile(new URL('THIRD_PARTY_NOTICES.md', outputDirectory), 'utf8');
for (const name of ['Inter', 'Geist Mono', 'Lucide Icons', 'SIL OPEN FONT LICENSE', 'ISC License', 'The MIT License']) {
  if (!notices.includes(name)) throw new Error(`aesir-html third-party notices are missing ${name}.`);
}

if (!source.includes('data:font/')) throw new Error('aesir-html all-in-one bundle must contain its webfonts.');

for (const name of componentFiles) {
  const componentSource = await readFile(new URL(`components/${name}`, outputDirectory), 'utf8');
  if (componentSource.includes('data:font/')) throw new Error(`${name} contains an inlined font.`);
}

if (coreCss.includes('@font-face')) throw new Error('aesir-core.css must not contain webfonts.');
if (!coreCss.includes('--ds-spacing-1')) throw new Error('aesir-core.css is missing Aesir design tokens.');
if (!coreCss.includes('--aesir-overlay-z-tooltip: 80')) throw new Error('aesir-core.css must keep tooltips above dialogs.');

if (iconsSource.includes('svelte.dev/e/')) {
  throw new Error('aesir-icons must contain SVG data only, not a second Svelte runtime.');
}

for (const icon of ['activity', 'list', 'telescope', 'origami', 'zoom-out']) {
  if (!iconsSource.includes(icon)) throw new Error(`aesir-icons is missing the ${icon} Lucide icon.`);
}

console.log('Checked the aesir-html all-in-one bundle, modular component files and runtime, shared core CSS, optional fonts, Lucide bundle, typography stylesheet, and Custom Element registrations.');
